#include <stdio.h>

void dobrar(int *p) {
    if (p != NULL) {
        *p = (*p) * 2; // Altera o valor original na memoria
    }
}

int main(void) {
    int x = 10;
    int *ptr = &x; // ptr guarda o endereco de x
    dobrar(ptr);
    printf("x = %d\n", x); // Imprime 20
    return 0;
}

#include <stdio.h>

typedef struct {
    int id;
    float nota;
} Aluno;

void darPontoExtra(Aluno *a, float bonus) {
    if (a != NULL) {
        a->nota += bonus; // Equivale a (*a).nota += bonus
    }
}

int main(void) {
    Aluno alu = {1, 7.0f};
    darPontoExtra(&alu, 1.5f);
    printf("Nota final: %.1f\n", alu.nota); // 8.5
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    FILE *fp = fopen("notas.txt", "w"); // "w" cria ou sobrescreve
    if (fp == NULL) {
        perror("Falha ao abrir arquivo");
        return EXIT_FAILURE;
    }
    fprintf(fp, "Aluno: Ana | Nota: %.1f\n", 9.0);
    fclose(fp);
    return 0;
}

#include <stdio.h>

typedef struct {
    int codigo;
    char nome[40]; // Array fixo (nunca char * ao usar fwrite direto)
    float preco;
} Produto;

int main(void) {
    Produto p = {10, "Teclado", 149.90f};
    FILE *fp = fopen("estoque.bin", "wb");
    if (fp != NULL) {
        fwrite(&p, sizeof(Produto), 1, fp);
        fclose(fp);
    }

    Produto lido;
    fp = fopen("estoque.bin", "rb");
    if (fp != NULL && fread(&lido, sizeof(Produto), 1, fp) == 1) {
        printf("%d - %s (R$ %.2f)\n", lido.codigo, lido.nome, lido.preco);
    }
    if (fp != NULL) fclose(fp);
    return 0;
}

